import hashlib
import hmac
import time
import sqlite3
import os
from flask import Flask, request, jsonify, g
from functools import wraps
import threading

app = Flask(__name__)
SECRET_KEY = os.environ.get('SECRET_KEY', os.urandom(32))
DB_PATH = '/tmp/authapp.db'

# Maximum lifetime of a session token in seconds (e.g. 1 hour)
TOKEN_MAX_AGE = 3600

# Thread-local session cache with TTL
class SessionCache:
    def __init__(self, ttl=300):
        self._cache = {}
        self._lock = threading.Lock()
        self._ttl = ttl

    def get(self, session_id):
        with self._lock:
            entry = self._cache.get(session_id)
            if entry is None:
                return None
            timestamp, data = entry
            # Check if cache entry is still valid
            elapsed = time.time() - timestamp
            if elapsed > self._ttl:
                del self._cache[session_id]
                return None
            return data

    def put(self, session_id, data):
        with self._lock:
            self._cache[session_id] = (time.time(), data)

    def invalidate(self, session_id):
        with self._lock:
            if session_id in self._cache:
                del self._cache[session_id]

session_cache = SessionCache(ttl=300)

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DB_PATH)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    conn = sqlite3.connect(DB_PATH)
    conn.executescript('''
        CREATE TABLE IF NOT EXISTS users (
            id INTEGER PRIMARY KEY,
            username TEXT UNIQUE NOT NULL,
            role INTEGER NOT NULL DEFAULT 0,
            password_hash TEXT NOT NULL DEFAULT ''
        );
        CREATE TABLE IF NOT EXISTS sessions (
            session_id TEXT PRIMARY KEY,
            user_id INTEGER NOT NULL,
            role_at_creation INTEGER NOT NULL,
            created_at REAL NOT NULL,
            revoked INTEGER NOT NULL DEFAULT 0,
            FOREIGN KEY (user_id) REFERENCES users(id)
        );
        CREATE TABLE IF NOT EXISTS resources (
            id INTEGER PRIMARY KEY,
            owner_id INTEGER NOT NULL,
            data TEXT,
            sensitivity INTEGER NOT NULL DEFAULT 0
        );
    ''')
    conn.commit()
    conn.close()

init_db()

# Role hierarchy: 0=guest, 1=user, 2=moderator, 3=admin, 4=superadmin
ROLE_NAMES = {0: 'guest', 1: 'user', 2: 'moderator', 3: 'admin', 4: 'superadmin'}

def _hmac_secret():
    return SECRET_KEY if isinstance(SECRET_KEY, bytes) else SECRET_KEY.encode()

def hash_password(password, salt=None):
    """Derive a salted password hash using PBKDF2-HMAC-SHA256."""
    if salt is None:
        salt = os.urandom(16)
    elif isinstance(salt, str):
        salt = bytes.fromhex(salt)
    dk = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 200000)
    return f"{salt.hex()}${dk.hex()}"

def verify_password(password, stored):
    """Verify a password against a stored salt$hash value."""
    if not stored or '$' not in stored:
        return False
    salt_hex, _hash_hex = stored.split('$', 1)
    candidate = hash_password(password, salt_hex)
    return hmac.compare_digest(candidate, stored)

def generate_session_token(user_id, role):
    """Generate a signed session token binding user_id and role."""
    timestamp = str(int(time.time()))
    payload = f"{user_id}:{role}:{timestamp}"
    signature = hmac.new(_hmac_secret(),
                         payload.encode(), hashlib.sha256).hexdigest()
    return f"{payload}:{signature}"

def verify_session_token(token):
    """Verify token signature and extract claims."""
    parts = token.rsplit(':', 1)
    if len(parts) != 2:
        return None
    payload, signature = parts
    expected_sig = hmac.new(_hmac_secret(),
                            payload.encode(), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(signature, expected_sig):
        return None
    fields = payload.split(':')
    if len(fields) != 3:
        return None
    try:
        created_at = int(fields[2])
    except (ValueError, IndexError):
        return None
    # Enforce token expiration
    if time.time() - created_at > TOKEN_MAX_AGE:
        return None
    return {'user_id': int(fields[0]), 'role': int(fields[1]), 'created_at': created_at}

def resolve_effective_role(session_claims, db):
    """Resolve the effective role for authorization.

    Security model: The effective role is the MINIMUM of:
    - The role embedded in the session token (role at session creation time)
    - The user's current role in the database

    This ensures that if a user is demoted, their existing sessions
    cannot be used with the old elevated role.
    """
    token_role = session_claims['role']
    user_id = session_claims['user_id']

    # Always fetch current role from database - no caching for security decisions
    row = db.execute('SELECT role FROM users WHERE id = ?', (user_id,)).fetchone()
    if row is None:
        return -1  # User deleted
    current_db_role = row['role']

    # The effective role is the lesser of token role and current DB role
    # This prevents privilege retention after demotion
    effective_role = min(token_role, current_db_role)
    return effective_role

def require_role(min_role):
    """Decorator that enforces minimum role requirement."""
    def decorator(f):
        @wraps(f)
        def decorated_function(*args, **kwargs):
            token = request.headers.get('X-Session-Token')
            if not token:
                return jsonify({'error': 'No session token'}), 401

            claims = verify_session_token(token)
            if claims is None:
                return jsonify({'error': 'Invalid session token'}), 401

            db = get_db()

            # Check if session is revoked
            sess = db.execute('SELECT revoked FROM sessions WHERE session_id = ?',
                            (token,)).fetchone()
            if sess and sess['revoked']:
                return jsonify({'error': 'Session revoked'}), 401

            effective_role = resolve_effective_role(claims, db)
            if effective_role < 0:
                return jsonify({'error': 'User not found'}), 401

            if effective_role < min_role:
                return jsonify({'error': 'Insufficient privileges'}), 403

            g.current_user_id = claims['user_id']
            g.effective_role = effective_role
            return f(*args, **kwargs)
        return decorated_function
    return decorator

@app.route('/api/login', methods=['POST'])
def login():
    data = request.get_json()
    username = data.get('username')
    password = data.get('password')
    if not username or not password:
        return jsonify({'error': 'Missing credentials'}), 400
    db = get_db()
    user = db.execute('SELECT id, role, password_hash FROM users WHERE username = ?', (username,)).fetchone()
    # Verify credentials; do not reveal whether the username exists.
    if user is None or not verify_password(password, user['password_hash']):
        return jsonify({'error': 'Invalid credentials'}), 401

    token = generate_session_token(user['id'], user['role'])
    db.execute('INSERT INTO sessions (session_id, user_id, role_at_creation, created_at, revoked) VALUES (?, ?, ?, ?, 0)',
               (token, user['id'], user['role'], time.time()))
    db.commit()
    return jsonify({'token': token, 'role': ROLE_NAMES.get(user['role'], 'unknown')})

@app.route('/api/admin/demote_user', methods=['POST'])
@require_role(3)  # Admin required
def demote_user():
    """Admin endpoint to demote a user's role."""
    data = request.get_json()
    target_user_id = data.get('user_id')
    new_role = data.get('new_role', 0)

    db = get_db()
    db.execute('UPDATE users SET role = ? WHERE id = ?', (new_role, target_user_id))
    db.commit()

    # Note: existing sessions will be checked against new DB role on next use

    return jsonify({'status': 'demoted', 'user_id': target_user_id, 'new_role': new_role})

@app.route('/api/admin/export_data', methods=['GET'])
@require_role(3)  # Admin required
def export_data():
    """Export all sensitive data - admin only."""
    db = get_db()
    resources = db.execute('SELECT * FROM resources WHERE sensitivity >= 2').fetchall()
    return jsonify({'data': [dict(r) for r in resources]})

@app.route('/api/moderator/manage_content', methods=['POST'])
@require_role(2)  # Moderator required
def manage_content():
    """Moderator content management."""
    data = request.get_json()
    action = data.get('action')
    resource_id = data.get('resource_id')

    db = get_db()
    if action == 'delete':
        db.execute('DELETE FROM resources WHERE id = ? AND sensitivity < 2', (resource_id,))
        db.commit()
    return jsonify({'status': 'ok'})

@app.route('/api/user/profile', methods=['GET'])
@require_role(1)  # User required
def get_profile():
    db = get_db()
    user = db.execute('SELECT id, username, role FROM users WHERE id = ?',
                     (g.current_user_id,)).fetchone()
    return jsonify(dict(user))

